      operationId: "flowfn.workflows.list",
      namespace: "tenant_1",
      region: "in-south",
    });
    expect(execute).toHaveBeenCalledWith({
      operationId: "flowfn.workflows.list",
      input: { limit: 25 },
      context,
    });
  });
