export interface FlowFnConfig {
  adapter:
    | FlowAdapter
    | "memory"
    | "redis"
    | "postgres"
    | "d1"
    | "sqs"
    | "kafka";
  namespace?: string;
  defaultJobOptions?: any;
  defaultQueueOptions?: QueueOptions;
