import type {
  BillableSubject,
  BillFnInstance,
  BillFnPlanDefinition,
} from "@billfn/core";
import {
  AdminError,
  type AdminOperationContext,
  type AdminOperationResult,
} from "@superfunctions/admin";
import type { BillFnAdminService, BillFnAdminServiceRequest } from "./index.js";

type JsonRecord = Record<string, unknown>;

export interface BillFnDomainAdminServiceOptions {
  billfn: BillFnInstance;
  /** Resolves the billable subject only after Super Console scope authorization. */
  subject(context: AdminOperationContext): BillableSubject | Promise<BillableSubject>;
}

function object(value: unknown, name: string): JsonRecord {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new AdminError("invalid_argument", `${name} must be an object.`);
  }
  return value as JsonRecord;
}

function string(value: unknown, name: string): string {
  if (typeof value !== "string" || value.length === 0) {
    throw new AdminError("invalid_argument", `${name} must be a non-empty string.`);
  }
  return value;
}

function optionalString(value: unknown, name: string): string | undefined {
  return value === undefined ? undefined : string(value, name);
}

function unwrap<T>(value: { ok: true; data: T } | { ok: false; error: { code: string; message: string; status: number; retryable: boolean; details?: unknown } }): T {
  if (value.ok) return value.data;
  const code = value.error.status === 404
    ? "not_found"
    : value.error.status === 403
      ? "forbidden"
      : value.error.status === 409
        ? "conflict"
        : value.error.status >= 500
          ? "dependency_unavailable"
          : "invalid_argument";
  throw new AdminError(code, value.error.message, {
    details: value.error.details,
    retryable: value.error.retryable,
  });
}

function asJson(value: object): JsonRecord {
  return { ...value };
}

function list(values: object[]): AdminOperationResult<JsonRecord> {
  return { ok: true, data: { items: values.map(asJson), nextCursor: null } };
}

function item(value: object): AdminOperationResult<JsonRecord> {
  return { ok: true, data: { item: asJson(value) } };
}

function accepted(value: object): AdminOperationResult<JsonRecord> {
  return { ok: true, data: { accepted: true, item: asJson(value) } };
}

function notFound(label: string): never {
  throw new AdminError("not_found", `${label} was not found for the active BillFn subject.`);
}

function products(plans: BillFnPlanDefinition[]): object[] {
  const grouped = new Map<string, { id: string; productKey: string; planCount: number }>();
  for (const plan of plans) {
    const existing = grouped.get(plan.productKey);
    grouped.set(plan.productKey, {
      id: plan.productKey,
      productKey: plan.productKey,
      planCount: (existing?.planCount ?? 0) + 1,
    });
  }
  return [...grouped.values()];
}

/** Delegates billing changes to BillFn so provider, catalog, entitlement and reconciliation invariants remain active. */
export function createBillFnDomainAdminService(
  options: BillFnDomainAdminServiceOptions,
): BillFnAdminService {
  return {
    async execute(request: BillFnAdminServiceRequest) {
      const input = object(request.input ?? {}, "input");
      const subject = await options.subject(request.context);
      const catalog = await options.billfn.getCatalog();
      const prices = catalog.plans.flatMap((plan) => plan.prices.map((price) => ({
        ...price,
        id: price.priceId,
        planKey: plan.planKey,
        productKey: plan.productKey,
      })));
      const plans = catalog.plans.map((plan) => ({ ...plan, id: plan.planKey }));

      switch (request.operationId) {
        case "billfn.products.list": return list(products(catalog.plans));
        case "billfn.products.get": {
          const value = products(catalog.plans).find((entry) => (entry as { id: string }).id === string(input.id, "id"));
          return value ? item(value) : notFound("Product");
        }
        case "billfn.plans.list": return list(plans);
        case "billfn.plans.get": {
          const value = plans.find((entry) => entry.id === string(input.id, "id"));
          return value ? item(value) : notFound("Plan");
        }
        case "billfn.prices.list": return list(prices);
        case "billfn.prices.get": {
          const value = prices.find((entry) => entry.id === string(input.id, "id"));
          return value ? item(value) : notFound("Price");
        }
        case "billfn.subscriptions.list": {
          const subscription = await options.billfn.subscriptionProvider.getActiveSubscription(subject);
          return list(subscription ? [subscription] : []);
        }
        case "billfn.subscriptions.get": {
          const subscription = await options.billfn.subscriptionProvider.getActiveSubscription(subject);
          return subscription?.id === string(input.id, "id") ? item(subscription) : notFound("Subscription");
        }
        case "billfn.entitlements.list": {
          const data = unwrap(await options.billfn.getEntitlements(subject));
          return list(data.entitlements ? [data.entitlements] : []);
        }
        case "billfn.entitlements.get": {
          const data = unwrap(await options.billfn.getEntitlements(subject));
          return data.entitlements?.id === string(input.id, "id") ? item(data.entitlements) : notFound("Entitlement");
        }
        case "billfn.usage.list": {
          const payload = object(input.filter ?? {}, "filter");
          const data = unwrap(await options.billfn.getUsage(subject, optionalString(payload.resource, "filter.resource")));
          return list(data.usage.map((entry) => ({ ...entry, id: entry.resource })));
        }
        case "billfn.usage.get": {
          const resource = string(input.id, "id");
          const data = unwrap(await options.billfn.getUsage(subject, resource));
          const value = data.usage.find((entry) => entry.resource === resource);
          return value ? item({ ...value, id: value.resource }) : notFound("Usage meter");
        }
        case "billfn.subscriptions.change-subscription": {
          const payload = object(input.payload, "payload");
          return accepted(unwrap(await options.billfn.changeSubscription({
            subject,
            subscriptionId: string(input.id, "id"),
            targetPriceId: string(payload.targetPriceId, "payload.targetPriceId"),
            effectiveAt: payload.effectiveAt as "immediate" | "next_renewal" | undefined,
            prorationBehavior: payload.prorationBehavior as "provider_default" | "prorate" | "none" | undefined,
            reason: optionalString(input.reason, "reason"),
          })));
        }
        case "billfn.subscriptions.cancel-subscription":
          return accepted(unwrap(await options.billfn.cancelSubscription({
            subject,
            subscriptionId: string(input.id, "id"),
            reason: optionalString(input.reason, "reason"),
          })));
        case "billfn.payments.refund-payment": {
          const payload = object(input.payload ?? {}, "payload");
          return accepted(unwrap(await options.billfn.refundCharge({
            subject,
            providerChargeId: string(input.id, "id"),
            subscriptionId: optionalString(payload.subscriptionId, "payload.subscriptionId"),
            mode: payload.mode as "full" | "prorated_remaining_period" | "custom" | undefined,
            amount: typeof payload.amount === "number" ? payload.amount : undefined,
            reason: optionalString(input.reason, "reason"),
          })));
        }
        case "billfn.reconciliation.reconcile-provider": {
          const payload = object(input.payload, "payload");
          return accepted(unwrap(await options.billfn.enqueueReconciliationJob({
            kind: string(payload.kind, "payload.kind") as "webhook-event" | "subscription-sync" | "account-scan" | "notification-history-backfill" | "webhook-replay",
            provider: payload.provider as Parameters<BillFnInstance["enqueueReconciliationJob"]>[0]["provider"],
            billingAccountId: optionalString(payload.billingAccountId, "payload.billingAccountId"),
            subscriptionId: optionalString(payload.subscriptionId, "payload.subscriptionId"),
            providerEventId: optionalString(payload.providerEventId, "payload.providerEventId"),
            cursor: optionalString(payload.cursor, "payload.cursor"),
          })));
        }
        default:
          throw new AdminError("not_found", `Unsupported BillFn admin operation: ${request.operationId}.`);
      }
    },
  };
}

