          ctx.set("key2", 42);
        })
        .step("read-values", async (ctx) => {
          expect(ctx.get("key1")).toBe("value1");
          expect(ctx.get("key2")).toBe(42);
        })
        .build();

      await workflow.execute({});
      await new Promise((r) => setTimeout(r, 100));
    });

    it("should track execution status", async () => {
