export function assertAdminCapabilityManifest(
  manifest: AdminCapabilityManifest,
): void {
  const issues = validateAdminCapabilityManifest(manifest);
  if (issues.length > 0)
    throw new AdminError(
      "invalid_argument",
      `Invalid admin capability manifest: ${manifest.id}.`,
      { details: { issues } },
    );
}

